// Une el lead (fila de Sheets) con el mensaje recibido y arma el prompt de clasificacion
const lead = $json;
const msg = $('Outlook: no leídos').item.json;
if (!lead || !lead.ID_Lead) { return []; }
const hoy = $now.toFormat('yyyy-LL-dd');
const texto = (msg.body && msg.body.content) ? msg.body.content : (msg.bodyPreview || '');
const system = [
'<identidad>Agente de Seguimiento Comercial B2B de ACCES GROUP. Manejas la respuesta de un prospecto. Venta consultiva, sin presion, sin precio prematuro, sin inventar datos.</identidad>',
'<tarea>1) Clasifica la intencion. 2) Actualiza score/etapa por evidencia. 3) Redacta contestacion (HTML simple, sin firma). 4) Si quiere reunirse, propone 2 franjas en horario laboral.</tarea>',
'<intenciones>interesado_agenda | pregunta | objecion | no_interesado | fuera_de_oficina | otro</intenciones>',
'<reglas>Espanol profesional, max ~120 palabras, 1 CTA. interesado_agenda: confirma y propone 2 fechas-hora ISO. objecion: escuchar-reconocer-pregunta de diagnostico, NO descuentes, NO presiones. no_interesado: agradece y cierra sin presion. fuera_de_oficina: no redactes, reprograma. Mueve etapa SOLO por evidencia.</reglas>',
'<salida>Responde SOLO este JSON sin ``` : {"intencion":"","nuevo_score":0,"nueva_etapa":"","nuevo_estado":"respondio|agendado|en_pipeline|nutrir|descartado","decision_agenda":false,"propuesta_reunion":{"titulo":"","duracion_min":30,"opciones":[]},"asunto_respuesta":"","cuerpo_html":"","fecha_siguiente_paso":"YYYY-MM-DD","razon":""}</salida>'
].join('\n');
const user = `Fecha de hoy: ${hoy}\nLead: ${lead.Empresa} — ${lead.Contacto} (${lead.Cargo})\nEtapa actual: ${lead.Etapa_Pipeline} | Score: ${lead.Score_ICP}\nAsunto enviado: ${lead.Asunto}\n\nRespuesta del prospecto:\n"""\n${texto}\n"""\n\nClasifica y redacta. Devuelve solo el JSON.`;
return [{ json: { ...lead, msg_id: msg.id, conversationId: msg.conversationId, system, user, hoy } }];

const FIRMA = '<br><br><table cellpadding="0" cellspacing="0" style="font-family:Arial,sans-serif;font-size:13px;color:#333"><tr><td style="padding-top:12px;border-top:2px solid #0a3d62"><strong style="color:#0a3d62">Nombre Apellido</strong><br><span style="color:#555">Ejecutivo Comercial — ACCES GROUP</span><br><a href="mailto:correo@accesgroup.com" style="color:#0a3d62">correo@accesgroup.com</a> | +52 55 0000 0000</td></tr></table>';
const resp = $json;
let text = '';
try { text = resp.content[0].text; } catch(e) { text = resp.body ? resp.body.content[0].text : '{}'; }
text = text.replace(/^```json/i,'').replace(/```$/,'').trim();
const data = JSON.parse(text);
const lead = $('Prep clasificación').item.json;
data.cuerpo_final = (data.cuerpo_html || '') + FIRMA;
// Calcular horario de reunion desde la 1a opcion propuesta
const pr = data.propuesta_reunion || {};
const opt = (pr.opciones && pr.opciones[0]) ? pr.opciones[0] : null;
const dur = pr.duracion_min || 30;
data.reunion_titulo = pr.titulo || ('ACCES GROUP <> ' + (lead.Empresa||''));
if (opt) {
  data.reunion_inicio = opt;
  const d = new Date(opt);
  data.reunion_fin = new Date(d.getTime() + dur*60000).toISOString().slice(0,19);
}
return [{ json: { ...lead, ...data } }];

// Captura el Event_Id REAL devuelto por Calendar (nunca inventar IDs)
const d = $('Parsear clasificación').item.json;
d.Event_Id = $json.id || '';
return [{ json: d }];

const d = $json;
if (!d.Event_Id) d.Event_Id = '';
return [{ json: d }];
